-- // RSHUB EXECUTOR GUARD BEGIN \\ --
-- // v1.0.1: static-environment compatible global registration and read-only notice cleanup. \\ --
-- // v1.0.0: named Xeno/Solara startup notice, clipboard recovery and owned GUI cleanup. \\ --
do
    local fallback = type(_G) == "table" and _G or nil
    local environment = fallback
    if type(getgenv) == "function" then
        local ok, value = pcall(getgenv)
        if ok and type(value) == "table" then environment = value end
    end
    local sharedEnvironment = environment ~= nil
    environment = environment or {}
    local executor
    for _, identify in ipairs({ identifyexecutor or false, getexecutorname or false }) do
        if type(identify) == "function" then
            local ok, value = pcall(identify)
            if ok and type(value) == "string" and value:match("%S") then executor = value; break end
        end
    end
    local name = type(executor) == "string" and executor:lower():match("^%s*([%a]+)") or ""
    local blocked = name == "xeno" and "Xeno" or name == "solara" and "Solara" or nil
    local key = "__rsHubExecutorNotice"
    for _, candidate in ipairs({ environment, fallback or false }) do
        if type(candidate) == "table" then
            local previous = rawget(candidate, key)
            if type(previous) == "table" and type(previous.Destroy) == "function" then pcall(previous.Destroy) end
        end
    end
    local function releaseMounted(host)
        if not host then return end
        pcall(function()
            local gui = host:FindFirstChild("RsHubUnsupportedExecutor")
            local cleanup = gui and gui:FindFirstChild("__RsHubExecutorNoticeCleanup")
            if cleanup and cleanup:IsA("BindableEvent") then cleanup:Fire() end
        end)
    end
    if type(gethui) == "function" then
        local ok, host = pcall(gethui)
        if ok then releaseMounted(host) end
    end
    if blocked then
        local url = "https://robloxscripts.com/executors-externals"
        local notice = { Active = true, Connections = {} }
        local function register(candidate)
            if type(candidate) ~= "table" then return false end
            local ok, retained = pcall(function() candidate[key] = notice; return rawget(candidate, key) == notice end)
            return ok and retained == true
        end
        local registered = sharedEnvironment and register(environment)
        if not registered and fallback ~= environment and register(fallback) then
            environment, registered = fallback, true
        end
        local function current()
            return notice.Active and (not registered or rawget(environment, key) == notice)
        end
        function notice.Destroy()
            if not notice.Active then return end
            notice.Active = false
            for _, connection in ipairs(notice.Connections) do pcall(function() connection:Disconnect() end) end
            table.clear(notice.Connections)
            if notice.Gui then pcall(function() notice.Gui:Destroy() end); notice.Gui = nil end
            if rawget(environment, key) == notice then pcall(function() environment[key] = nil end) end
        end
        local function copyLink()
            for _, copy in ipairs({ setclipboard or false, toclipboard or false }) do
                if type(copy) == "function" then
                    local ok, result = pcall(copy, url)
                    if ok and result ~= false then return true end
                end
            end
            return false
        end
        local copied = copyLink()
        local function copyStatus(ok)
            return ok and "Executor list link copied to your clipboard."
                or "Could not copy automatically. Select and copy the link below."
        end
        local function mount(gui)
            local function try(host)
                if not host or not current() then return false end
                releaseMounted(host)
                local parented = pcall(function() gui.Parent = host end)
                return parented and gui.Parent == host
            end
            if type(gethui) == "function" then
                local ok, host = pcall(gethui)
                if ok and try(host) then return true end
            end
            local ok, core = pcall(function() return game:GetService("CoreGui") end)
            if ok and try(core) then return true end
            local playerOk, playerGui = pcall(function()
                local player = game:GetService("Players").LocalPlayer
                return player and (player:FindFirstChildOfClass("PlayerGui") or player:FindFirstChild("PlayerGui"))
            end)
            if playerOk and try(playerGui) then return true end
            return false
        end
        local ok, failure = pcall(function()
            local function make(class, name, parent, properties)
                local object = Instance.new(class)
                if class == "ScreenGui" then notice.Gui = object end
                object.Name = name
                for property, value in pairs(properties or {}) do object[property] = value end
                object.Parent = parent
                return object
            end
            local gui = make("ScreenGui", "RsHubUnsupportedExecutor", nil, {
                ResetOnSpawn = false, IgnoreGuiInset = true, DisplayOrder = 1000000,
                ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
            })
            if not registered then
                local cleanup = make("BindableEvent", "__RsHubExecutorNoticeCleanup", gui)
                notice.Connections[#notice.Connections + 1] = cleanup.Event:Connect(notice.Destroy)
            end
            local panel = make("Frame", "Notice", gui, {
                AnchorPoint = Vector2.new(.5, .5), Position = UDim2.fromScale(.5, .5),
                Size = UDim2.new(1, -32, 0, 308), BackgroundColor3 = Color3.fromRGB(15, 19, 30),
                BorderSizePixel = 0,
            })
            make("UISizeConstraint", "Bounds", panel, { MaxSize = Vector2.new(520, 308) })
            make("UICorner", "Corner", panel, { CornerRadius = UDim.new(0, 10) })
            local function label(name, text, top, height, size)
                return make("TextLabel", name, panel, {
                    Position = UDim2.new(0, 20, 0, top), Size = UDim2.new(1, -40, 0, height),
                    BackgroundTransparency = 1, Text = text, TextWrapped = true,
                    TextColor3 = Color3.fromRGB(235, 239, 247), TextSize = size or 15,
                    Font = Enum.Font.Gotham, TextXAlignment = Enum.TextXAlignment.Left,
                    TextYAlignment = Enum.TextYAlignment.Center,
                })
            end
            label("Title", blocked .. " is not supported", 18, 30, 21)
            label("Message", "rsHub needs a better, supported executor.\nVolcano, Real and Madium are supported.", 55, 58)
            notice.Status = label("ClipboardStatus", copyStatus(copied), 116, 42, 13)
            make("TextBox", "ExecutorLink", panel, {
                Position = UDim2.new(0, 20, 0, 165), Size = UDim2.new(1, -40, 0, 32),
                BackgroundColor3 = Color3.fromRGB(29, 35, 49), BorderSizePixel = 0,
                Text = url, TextEditable = false, ClearTextOnFocus = false,
                TextColor3 = Color3.fromRGB(235, 239, 247), TextSize = 12, Font = Enum.Font.Gotham,
            })
            local button = make("TextButton", "CopyExecutorList", panel, {
                Position = UDim2.new(0, 20, 0, 207), Size = UDim2.new(1, -40, 0, 42),
                BackgroundColor3 = Color3.fromRGB(245, 158, 11), BorderSizePixel = 0,
                Text = "Best place for free & paid executors", TextWrapped = true,
                TextColor3 = Color3.fromRGB(15, 19, 30), TextSize = 15, Font = Enum.Font.Gotham,
            })
            local close = make("TextButton", "Close", panel, {
                Position = UDim2.new(0, 20, 0, 260), Size = UDim2.new(1, -40, 0, 28),
                BackgroundTransparency = 1, Text = "Close", TextColor3 = Color3.fromRGB(190, 198, 215),
                TextSize = 14, Font = Enum.Font.Gotham,
            })
            notice.Connections[#notice.Connections + 1] = button.Activated:Connect(function()
                if current() then notice.Status.Text = copyStatus(copyLink()) end
            end)
            notice.Connections[#notice.Connections + 1] = close.Activated:Connect(notice.Destroy)
            if not mount(gui) then
                task.spawn(function()
                    for _ = 1, 60 do
                        task.wait(.25)
                        if not current() then return end
                        if mount(gui) then return end
                    end
                    if current() then
                        warn("rsHub: " .. blocked .. " is not supported. Use Volcano, Real or Madium. " .. url .. " " .. copyStatus(copied))
                        notice.Destroy()
                    end
                end)
            end
        end)
        if not ok then
            notice.Destroy()
            warn("rsHub: " .. blocked .. " is not supported. Use Volcano, Real or Madium. " .. url .. " " .. copyStatus(copied))
        end
        return
    end
end
-- // RSHUB EXECUTOR GUARD END \\ --

-- Anonymous run stats for robloxscripts.com Script Ops (https://robloxscripts.com/script-ops). It runs in
-- the background and can never block or break the loader. Skipped when getgenv().RSOPS_OFF is true or
-- rsops/optout.txt exists. Keep the trailing semicolon.
task.spawn(pcall, function() local g = getgenv and getgenv() or {}; if g.RSOPS_OFF == true or g.RSOps and g.RSOps._off == true or isfile and select(2, pcall(isfile, "rsops/optout.txt")) == true then return end; loadstring(game:HttpGet("https://robloxscripts.com/ops/v1.lua")){ id = "ops_onszkwuf2qk5" } end);

-- ScriptBlox run tracker. Its separate background task cannot delay or break the loader.
task.spawn(function()
    pcall(function()
        loadstring(game:HttpGet("https://scriptblox.com/ingest/clientv2.lua"))("proj_ef4c9933a985", "1.0.0", false)
    end)
end)

