local function restoreCapability()
    for _, fn in pairs({ setthreadidentity, setidentity, setcontext }) do
        if type(fn) == "function" then pcall(fn, 8) end
    end
end

local env = getgenv()
local DEVICE_CONFIG = "VibeUI/Device.json"
local function validDevicePreference(value)
    return value == "Auto" or value == "Mobile" or value == "PC"
end

local function detectDevice()
    local ok, mode = pcall(function()
        local input = game:GetService("UserInputService")
        local preferredOk, preferred = pcall(function() return input.PreferredInput.Name end)
        if preferredOk then
            if preferred == "Touch" then return "Mobile" end
            if preferred == "KeyboardAndMouse" then return "PC" end
        end
        return input.TouchEnabled and (not input.KeyboardEnabled or not input.MouseEnabled) and "Mobile" or "PC"
    end)
    return ok and mode or "PC"
end

local device = rawget(env, "__VibeUIDevice")
if type(device) ~= "table" then device = {} end
local preference = rawget(device, "Preference")
if not validDevicePreference(preference) then
    preference = "Auto"
    if type(readfile) == "function" then
        local ok, saved = pcall(function()
            local encoded = readfile(DEVICE_CONFIG)
            if type(encoded) ~= "string" or #encoded > 1024 then return end
            return game:GetService("HttpService"):JSONDecode(encoded)
        end)
        if ok and type(saved) == "table" and saved.schema_version == 1 and validDevicePreference(saved.preference) then
            preference = saved.preference
        end
    end
end
device.Preference, device.Detected = preference, detectDevice()
device.Mode = preference == "Auto" and device.Detected or preference
env.__VibeUIDevice = device

local function setDevicePreference(value)
    if not validDevicePreference(value) then return end
    device.Preference = value
    device.Mode = value == "Auto" and device.Detected or value
    if type(writefile) == "function" then
        pcall(function()
            if type(makefolder) == "function" then pcall(makefolder, "VibeUI") end
            writefile(DEVICE_CONFIG, game:GetService("HttpService"):JSONEncode({ schema_version = 1, preference = value }))
        end)
    end
end

local previous = rawget(env, "__FreeNoKeyLoader")
if type(previous) == "table" and type(previous.Close) == "function" then
    pcall(previous.Close)
end

local session = { active = true, connections = {}, Device = device }
env.__FreeNoKeyLoader = session
env.__FreeNoKey = { loader = LOADER_VERSION, status = "detecting" }

local function alive()
    return session.active and env.__FreeNoKeyLoader == session
end

local function track(connection)
    session.connections[#session.connections + 1] = connection
    return connection
end

local function closeUi()
    restoreCapability()
    for _, connection in ipairs(session.connections) do
        pcall(function() connection:Disconnect() end)
    end
    table.clear(session.connections)
    if session.GUI then
        pcall(function() session.GUI:Destroy() end)
        session.GUI = nil
    end
    session.UI = nil
end

session.Close = function()
    session.active = false
    closeUi()
    if env.__FreeNoKeyLoader == session then
        env.__FreeNoKeyLoader = nil
        if type(env.__FreeNoKey) == "table" then env.__FreeNoKey.status = "closed" end
    end
end

local function httpGet(url)
    restoreCapability()
    return game:HttpGet(url)
end

local function rawUrl(path)
    return BASE .. path .. "?v=" .. tostring(tick())
end

local function copyText(text)
    local setclip = setclipboard or set_clipboard or (syn and syn.write_clipboard)
    if type(setclip) ~= "function" then return false end
    return pcall(setclip, text)
end

local function catalog()
    local seen, entries = {}, {}
    for _, entry in pairs(GAMES) do
        if not seen[entry.file] then
            seen[entry.file] = true
            entries[#entries + 1] = entry
        end
    end
    table.sort(entries, function(a, b) return a.name:lower() < b.name:lower() end)
    return entries
end

