    local function viewportSize()
        local viewport = backdrop.AbsoluteSize
        if viewport.X > 0 and viewport.Y > 0 then return viewport end
        local camera = workspace.CurrentCamera
        return camera and camera.ViewportSize or Vector2.new(1280, 720)
    end
    fit = function()
        local viewport = viewportSize()
        local mobile = device.Mode == "Mobile"
        local stripHeight, footerHeight = mobile and 40 or 32, mobile and 40 or 30
        local bodyTop = 62 + stripHeight
        local bodyBottom = footerHeight + 34
        deviceStrip.Size = UDim2.new(1, -32, 0, stripHeight)
        body.Position = UDim2.fromOffset(16, bodyTop)
        footer.Position = UDim2.new(0, 16, 1, -footerHeight - 14)
        footer.Size = UDim2.new(1, mobile and -68 or -44, 0, footerHeight)
        feedback.Position = UDim2.new(0, 16, 1, -footerHeight - 31)
        feedback.Size = UDim2.new(1, mobile and -68 or -44, 0, 14)
        search.Size = UDim2.new(1, 0, 0, mobile and 40 or 32)
        copyGame.Size = UDim2.new(1, 0, 0, mobile and 40 or 30)
        close.Position = UDim2.new(1, mobile and -44 or -34, 0, mobile and 3 or 14)
        close.Size = UDim2.fromOffset(mobile and 40 or 22, mobile and 40 or 22)
        grip.Size = UDim2.fromOffset(mobile and 40 or 22, mobile and 40 or 22)
        tooltip.Position = UDim2.new(1, -82, 1, mobile and -100 or -90)
        brand.TextSize = mobile and 14 or 17
        body.ScrollBarThickness = mobile and 5 or 3
        gui:SetAttribute("DevicePreference", device.Preference)
        gui:SetAttribute("DeviceMode", device.Mode)
        for value, option in pairs(modeButtons) do
            option.Text = value == "Auto" and ("Auto (" .. device.Detected .. ")") or value
            option.BackgroundTransparency = device.Preference == value and 0 or 0.18
            option.BackgroundColor3 = device.Preference == value and SITE_THEME.Accent or SITE_THEME.Element
            option.TextColor3 = device.Preference == value and SITE_THEME.Background or SITE_THEME.Text
        end
        local maxWidth, maxHeight = math.max(1, viewport.X - 28), math.max(1, viewport.Y - 28)
        local width = math.clamp(geometry.width, math.min(292, maxWidth), maxWidth)
        local defaultHeight = showCatalog and (mobile and 552 or 542) or (mobile and 322 or 312)
        local height = math.clamp(geometry.resized and geometry.height or defaultHeight,
            math.min(mobile and 264 or 200, maxHeight), maxHeight)
        body.Size = UDim2.new(1, -32, 0, math.max(1, height - bodyTop - bodyBottom))
        local x = geometry.moved and geometry.x or (viewport.X - width) / 2
        local y = geometry.moved and geometry.y or (viewport.Y - height) / 2
        x, y = math.clamp(x, 14, math.max(14, viewport.X - width - 14)),
            math.clamp(y, 14, math.max(14, viewport.Y - height - 14))
        geometry.x, geometry.y = x, y
        panel.Size = UDim2.fromOffset(width, height)
        panel.Position = UDim2.fromOffset(x, y)
        local columns = width >= 460 and 2 or 1
        layout.FillDirectionMaxCells = columns
        layout.CellSize = UDim2.new(1 / columns, columns == 2 and -5 or 0, 0, mobile and 44 or 40)
    end
    local inputService = game:GetService("UserInputService")
    local function beginGesture(mode, input)
        local kind = input.UserInputType
        if not alive() or (kind ~= Enum.UserInputType.MouseButton1 and kind ~= Enum.UserInputType.Touch) then return end
        gesture = {
            mode = mode, input = input, kind = kind, startX = input.Position.X, startY = input.Position.Y,
            x = geometry.x, y = geometry.y, width = panel.AbsoluteSize.X, height = panel.AbsoluteSize.Y,
        }
        tooltip.Visible = false
    end
    track(titlebar.InputBegan:Connect(function(input) beginGesture("drag", input) end))
    track(grip.InputBegan:Connect(function(input) beginGesture("resize", input) end))
    track(inputService.InputChanged:Connect(function(input)
        if not alive() or not gesture then return end
        if gesture.kind == Enum.UserInputType.Touch then
            if input ~= gesture.input then return end
        elseif input.UserInputType ~= Enum.UserInputType.MouseMovement then return end
        local dx, dy = input.Position.X - gesture.startX, input.Position.Y - gesture.startY
        if gesture.mode == "drag" then
            geometry.moved = true
            geometry.x, geometry.y = gesture.x + dx, gesture.y + dy
        else
            geometry.moved, geometry.resized = true, true
            geometry.x, geometry.y = gesture.x, gesture.y
            local viewport = viewportSize()
            geometry.width = math.clamp(gesture.width + dx, math.min(292, viewport.X - 28),
                math.max(292, viewport.X - gesture.x - 14))
            geometry.height = math.clamp(gesture.height + dy, math.min(200, viewport.Y - 28),
                math.max(200, viewport.Y - gesture.y - 14))
        end
        fit()
    end))
    track(inputService.InputEnded:Connect(function(input)
        if gesture and (input == gesture.input
            or (gesture.kind ~= Enum.UserInputType.Touch and input.UserInputType == gesture.kind)) then
            gesture = nil
        end
    end))
    track(inputService.WindowFocusReleased:Connect(function() gesture = nil end))
    local function filter()
        local query = search.Text:lower():match("^%s*(.-)%s*$")
        local found = 0
        for _, row in ipairs(rows) do
            row.frame.Visible = query == "" or row.name:find(query, 1, true) ~= nil
            if row.frame.Visible then found += 1 end
        end
        count.Text = query == "" and ("Published games (" .. #entries .. ")")
            or ("Published games (" .. found .. " of " .. #entries .. ")")
        empty.Visible = found == 0
        body.CanvasPosition = Vector2.new()
    end
    track(search:GetPropertyChangedSignal("Text"):Connect(filter))
    track(backdrop:GetPropertyChangedSignal("AbsoluteSize"):Connect(fit))

    function handle:SetContext()
        metadata.Text = "Place " .. placeId .. "  |  Universe " .. gameId
        metadata.Visible = placeId ~= "0" or gameId ~= "0"
    end
    function handle:SetState(title, detail, phase, list)
        heading.Text = title
        description.Text = detail
        errorDetails.Visible = false
        joinLink = nil
        copyGame.Visible = false
        feedback.Text = ""
        body.CanvasPosition = Vector2.new()
        showCatalog = list == true
        published.Visible = showCatalog
        if showCatalog then
            for _, row in ipairs(rows) do
                if row.icon.Image ~= row.image then row.icon.Image = row.image end
            end
        end
        progress.Visible = phase ~= nil
        if phase then step.Text = phase end
        fit()
    end
    function handle:SetProgress(value)
        fill.Size = UDim2.fromScale(math.clamp(value, 0, 1), 1)
    end
    function handle:Feedback(value)
        feedback.Text = value
    end
    function handle:SetError(value)
        errorDetails.Text = value
        errorDetails.Visible = value ~= ""
    end
    function handle:SetJoinFallback(targetPlace)
        joinLink = "https://www.roblox.com/games/" .. tostring(targetPlace)
        copyGame.Visible = true
    end
    function handle:SetBusy(value)
        retry.Text = value and "Refreshing..." or "Refresh"
        retry.Active = not value
    end
    function handle:SetJoining(value)
        retry.Text = value and "Joining..." or "Refresh"
        retry.Active = not value
        for _, row in ipairs(rows) do
            row.frame.Active = not value and row.canJoin
            row.frame.Selectable = not value and row.canJoin
        end
    end
    function handle:Close()
        if session.UI == self then closeUi() end
    end
    filter()
    fit()
    local localPlayer = game:GetService("Players").LocalPlayer
    track(game:GetService("TeleportService").TeleportInitFailed:Connect(function(player, _, message, targetPlace, options)
        local pending = session.joinPending
        if alive() and session.GUI == gui and pending and player == localPlayer
            and tonumber(targetPlace) == pending.place and joinFailed then
            -- // Ignore untagged or late failures from another join attempt. \\ --
            local ok, data = pcall(function() return options:GetTeleportData() end)
            if ok and type(data) == "table" and type(pending.token) == "string"
                and data.FreeNoKeyJoin == pending.token then
                joinFailed(pending, message)
            end
        end
    end))
    return handle
end

do
    local ok, handle = pcall(createUi)
    if ok then
        session.UI = handle
    else
        closeUi()
        warn("[robloxscripts.com Hub] Startup UI unavailable: " .. tostring(handle))
    end
end

local function uiCall(method, ...)
    if not alive() or not session.UI then return end
    restoreCapability()
    local fn = session.UI[method]
    if type(fn) == "function" then pcall(fn, session.UI, ...) end
end

local function setState(status, title, detail, phase, list)
    if not alive() then return end
    env.__FreeNoKey.status = status
    uiCall("SetState", title, detail, phase, list)
end

local function fail(title, detail, errorText)
    if not alive() then return end
    lastError = tostring(errorText or ""):sub(1, 4096)
    env.__FreeNoKey.error = lastError ~= "" and lastError or nil
    setState("failed", title, detail, nil, false)
    if lastError ~= "" then
        uiCall("SetError", lastError:gsub("[%c]+", " "):sub(1, 1024))
    end
    if not session.UI then warn("[robloxscripts.com Hub] " .. title .. ": " .. detail .. " " .. lastError) end
end

joinFailed = function(pending, errorText)
    if not alive() or session.joinPending ~= pending then return end
    session.joinPending = nil
    env.__FreeNoKey.targetPlaceId = nil
    lastError = tostring(errorText or "Roblox could not connect to this game."):sub(1, 4096)
    env.__FreeNoKey.error = lastError
    local reason = lastError:lower()
    local blocked = reason:find("different creator", 1, true) or reason:find("restricted", 1, true)
        or reason:find("773", 1, true)
    local detail = lastError:gsub("[%c]+", " "):sub(1, 1024)
    if reason:find("different creator", 1, true) then
        detail = "Cross-game teleports are disabled by this experience."
    elseif blocked then
        detail = "Roblox has restricted access to this destination."
    end
    setState("teleport_failed", blocked and "Teleport blocked" or "Could not join game", pending.name, nil, true)
    uiCall("SetError", detail)
    uiCall("SetJoinFallback", pending.place)
    uiCall("SetJoining", false)
end

joinGame = function(entry)
    if not alive() or refreshing or session.joinPending then return end
    local info = GAME_CATALOG[entry.file]
    if not info then
        uiCall("Feedback", "Game unavailable.")
        return
    end
    local pending = { name = entry.name, place = info.place }
    session.joinPending = pending
    dispatchCancelled = true
    lastError = ""
    env.__FreeNoKey.error = nil
    env.__FreeNoKey.targetPlaceId = pending.place
    setState("teleporting", "Joining game", entry.name, nil, true)
    uiCall("SetJoining", true)
    task.delay(20, function()
        joinFailed(pending, "The connection timed out. Please try again.")
    end)
    restoreCapability()
    local ok, errorText = pcall(function()
        if alive() and session.joinPending == pending then
            pending.token = game:GetService("HttpService"):GenerateGUID(false)
            game:GetService("TeleportService"):Teleport(pending.place, game:GetService("Players").LocalPlayer,
                { FreeNoKeyJoin = pending.token })
        end
    end)
    if not ok then joinFailed(pending, errorText) end
end

local function validSource(source)
    if type(source) ~= "string" or #source < 32 then return false end
    local head = source:sub(1, 160):lower()
    return not head:find("<!doctype", 1, true) and not head:find("<html", 1, true)
end

local function fetch(path)
    local result = { done = false }
    task.spawn(function()
        local ok, value = pcall(httpGet, rawUrl(path))
        result.ok, result.value, result.done = ok, value, true
    end)
    local deadline = os.clock() + 20
    while alive() and not result.done and os.clock() < deadline do task.wait(0.05) end
    if not alive() then return nil, "cancelled" end
    if not result.done then return nil, "The request timed out." end
    if not result.ok then return nil, tostring(result.value) end
    if not validSource(result.value) then return nil, "The server did not return a script." end
    return result.value
end

retryLoader = function()
    if not alive() or refreshing or session.joinPending then return end
    refreshing = true
    dispatchCancelled = true
    lastError = ""
    env.__FreeNoKey.error = nil
    uiCall("SetBusy", true)
    setState("detecting", "Checking for updates", "Fetching the latest published loader.", "Refresh loader", false)
    uiCall("SetProgress", 0.15)
    local source, err = fetch("loader.luau")
    if not alive() then return end
    if source then
        restoreCapability()
        local ok, fn, compileErr = pcall(loadstring, source, "=FreeNoKey.Refresh")
        if ok and type(fn) == "function" then
            closeUi()
            local ran, runErr = pcall(fn)
            if not ran and not alive() then
                warn("[robloxscripts.com Hub] Refreshed loader failed: " .. tostring(runErr))
            end
            if alive() then
                if ran then
                    session.active = false
                    env.__FreeNoKeyLoader = nil
                else
                    local made, handle = pcall(createUi)
                    if made then session.UI = handle else closeUi() end
                    uiCall("SetContext")
                    fail("Refresh failed", "The latest loader could not start.", runErr)
                end
            end
        else
            fail("Refresh failed", "The latest loader could not compile.", ok and compileErr or fn)
        end
    else
        fail("Refresh failed", "The published loader could not be downloaded.", err)
    end
    refreshing = false
    uiCall("SetBusy", false)
end

if not game:IsLoaded() then game.Loaded:Wait() end
if not alive() or dispatchCancelled then return end

do
    local deadline = os.clock() + 2
    repeat
        pcall(function()
            placeId = tostring(game.PlaceId or 0)
            gameId = tostring(game.GameId or 0)
        end)
        match = GAMES[placeId] or GAMES[gameId]
        if match or (placeId ~= "0" and gameId ~= "0") then break end
        task.wait(0.05)
    until not alive() or os.clock() >= deadline
end
if not alive() or dispatchCancelled then return end

detectedName = match and match.name or "This experience"
env.__FreeNoKey.placeId = placeId
env.__FreeNoKey.universeId = gameId
env.__FreeNoKey.name = detectedName
env.__FreeNoKey.version = match and match.version or ""
env.__FreeNoKey.file = match and match.file or ""
env.__FreeNoKey.updatedAt = match and match.updatedAt or nil
uiCall("SetContext")

if not match then
    setState("unsupported", "No published script for this game", detectedName, nil, true)
    task.spawn(function()
        local ok, info = pcall(function()
            return game:GetService("MarketplaceService"):GetProductInfoAsync(tonumber(placeId), Enum.InfoType.Asset)
        end)
        if ok and type(info) == "table" and type(info.Name) == "string" and alive()
            and env.__FreeNoKey.status == "unsupported" then
            detectedName = info.Name
            env.__FreeNoKey.name = detectedName
            uiCall("SetState", "No published script for this game", detectedName, nil, true)
        end
    end)
    if not session.UI then
        local names = {}
        for _, entry in ipairs(entries) do names[#names + 1] = entry.name end
        warn("[robloxscripts.com Hub] No published script for place " .. placeId
            .. ". Published games: " .. table.concat(names, ", "))
    end
    return
end

setState("downloading", match.name, "Script " .. match.version .. "  |  Downloading", "2 / 3  Download script", false)
uiCall("SetProgress", 0.35)
local source, downloadErr = fetch("scripts/" .. match.file)
if not alive() or dispatchCancelled then return end
if not source then
    fail("Download failed", match.name .. " could not be downloaded. Refresh to try again.", downloadErr)
    return
end

setState("compiling", match.name, "Script " .. match.version .. "  |  Checking script", "3 / 3  Start script", false)
uiCall("SetProgress", 0.75)
restoreCapability()
local compiled, fn, compileErr = pcall(loadstring, source, "=FreeNoKey." .. match.file)
if not alive() then return end
if not compiled or type(fn) ~= "function" then
    fail("Script could not compile", match.name .. " " .. match.version, compiled and compileErr or fn)
    return
end

setState("starting", match.name, "Script " .. match.version .. "  |  Starting", "3 / 3  Start script", false)
uiCall("SetProgress", 1)
closeUi()
restoreCapability()
local ok, runErr = pcall(fn)
if not alive() then return end
if not ok then
    local made, handle = pcall(createUi)
    if made then session.UI = handle else closeUi() end
    uiCall("SetContext")
    fail("Script could not start", match.name .. " " .. match.version, runErr)
else
    env.__FreeNoKey.status = "started"
end
